onClick:
{{
  (async function() {
    try {
      // 1. ACTION BASE DE DONNÉES
      const res = await Insert_Article_Rapide.run();
      await storeValue('nouvel_article_id', res[0].ID_Article);
      await Get_Articles_Options.run(); 

      // 2. ACTIONS VISUELLES (On ferme l'article, ON ROUVRE LA LIGNE)
      closeModal('modal_add_article');
      showModal('modal_add_ligne'); // ⬅️ La ligne magique est ici !
      showAlert('Article créé et sélectionné !', 'success');

      // 3. NETTOYAGE
      setTimeout(() => {
        resetWidget('modal_add_article', true);
      }, 500);

    } catch (error) {
      showAlert('Erreur : ' + error.message, 'error');
    }
  })()
}}
